package com.simon.mytasks;
import android.content.*;import android.view.*;import android.widget.*;import org.json.*;
final class CitationUi {
 static void chips(MainActivity a,LinearLayout parent,JSONObject message){for(String warning:CitationPolicy.warnings(message)){TextView notice=a.label(warning,14,a.muted);notice.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);a.add(parent,notice);}JSONArray sources=CitationPolicy.sources(message);for(int i=0;i<sources.length();i++){JSONObject source=sources.optJSONObject(i);if(source==null)continue;final JSONObject s=source;Button chip=a.button("["+(i+1)+"] "+source.optString("label",source.optString("subject","Source")),()->panel(a,s));a.ui.quiet(chip);chip.setContentDescription("Source "+(i+1)+", "+source.optString("label","View context"));a.add(parent,chip);}}
 static void panel(MainActivity a,JSONObject s){if(!s.optString("kind").equals("email")&&!s.optString("kind").equals("saved_email")){String url=s.optString("url");a.dialogBuilder().setTitle(s.optString("label","Source")).setMessage(s.optString("excerpt","")+"\n"+url+"\n"+s.optString("verification","Unverified")).setNegativeButton("Close",null).setPositiveButton(CitationPolicy.safe(url)?"Open in browser":"Unavailable",(d,w)->{if(CitationPolicy.safe(url))try{a.startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(url)).addCategory(Intent.CATEGORY_BROWSABLE));}catch(Exception e){a.notice("Source unavailable","No browser is available.");}}).show();return;}
  final Store.Account owner=a.account;final long generation=a.surfaces.generation();String task=s.optString("task_id"),resource=s.optString("resource_id");if(task.isEmpty()||resource.isEmpty()){a.notice("Email source unavailable","This older citation has no validated source identity. No email or URL was guessed.");return;}
  Api.IO.execute(()->{try{JSONObject detail=new EmailReplyClient((m,p,b)->new Api(owner).call(m,p,b)).detail(task,resource);a.main.post(()->{if(!a.alive(owner)||!a.surfaces.current(generation))return;showDetail(a,detail);});}catch(Exception e){a.main.post(()->{if(a.alive(owner)&&a.surfaces.current(generation))a.notice("Email source unavailable","Saved email context could not be resolved. No draft was created and no update acknowledged.");});}});
 }
 static void showDetail(MainActivity a,JSONObject detail){JSONObject s=detail.optJSONObject("source");if(s==null){a.notice("Source unavailable","No validated source metadata returned.");return;}StringBuilder text=new StringBuilder();for(String k:new String[]{"account_label","sender","subject","date","excerpt","reason"})if(!s.isNull(k)&&!s.optString(k).isEmpty())text.append(s.optString(k)).append("\n\n");JSONArray thread=detail.optJSONArray("thread");if(thread!=null)for(int i=0;i<thread.length();i++){JSONObject m=thread.optJSONObject(i);if(m!=null)text.append(m.optString("sender")).append(" · ").append(m.optString("date")).append("\n").append(m.optString("subject")).append("\n").append(m.optString("body")).append("\n\n");}a.fullMessage(text.toString());}
}
